# Lesson 16 of MKTG90037: pricing, the cost side (Week 10, first half): the six pricing myths, elasticity, pricing objectives, cost-
# based pricing, scale, target costing and the learning curve. Brand: Coles (FY26: 311 million of cost savings funding value).
# Instruments: price, volume and profit (Dial), scale and unit cost (Dial), which myth (Tag).
from mk import *  # noqa: F403


def L16(CID):
    SK = 'mk.pricing-cost'
    cats = [dict(id='m1', label=T('1: Costs are the basis for pricing', '1：成本是定价的依据')), dict(id='m2', label=T('2: Small price changes have little impact', '2：小幅价格变化影响很小')), dict(id='m3', label=T('3: Customers are highly price sensitive', '3：顾客对价格高度敏感')),
            dict(id='m4', label=T('4: Products are hard to differentiate', '4：产品很难差异化')), dict(id='m5', label=T('5: High share means high profit', '5：高份额就是高利润')), dict(id='m6', label=T('6: Managing price means changing prices', '6：管理价格就是改价格'))]
    items = [
        dict(text=T('“Pricing has to start from what the customer values, not from our cost.”', '“定价要从顾客看重什么出发，而不是从我们的成本出发。”'), cat='m1', why=T('The truth behind myth 1: pricing has to be based on customer value.', '迷思 1 背后的真相：定价必须以顾客价值为基础。')),
        dict(text=T('“A one percent price change moves company profit a lot: fight for pennies.”', '“价格变动百分之一，就能大幅改变公司利润：为每一分钱而战。”'), cat='m2', why=T('The truth behind myth 2: small price changes have an extremely significant effect on profitability.', '迷思 2 背后的真相：小幅价格变化对盈利有极其显著的影响。')),
        dict(text=T('“Buyers often do not know what they pay; businesses care about total cost of ownership.”', '“买家往往不清楚自己付了多少；企业买家在乎的是总拥有成本。”'), cat='m3', why=T('The truth behind myth 3: customers are frequently unaware of prices paid, so segment them by needs.', '迷思 3 背后的真相：顾客常常不清楚所付价格，所以要按需求细分。')),
        dict(text=T('“Even commodities can be differentiated; treating a product as a commodity becomes a self-fulfilling prophecy.”', '“连大宗商品也能差异化；把产品当作大路货就会变成自我实现的预言。”'), cat='m4', why=T('The truth behind myth 4.', '迷思 4 背后的真相。')),
        dict(text=T('“Market share and profitability are not correlated: aim for leadership in customer insight.”', '“市场份额和盈利能力并不相关：要追求在顾客洞察上领先。”'), cat='m5', why=T('The truth behind myth 5.', '迷思 5 背后的真相。')),
        dict(text=T('“Managing price means improving systems, processes and skills, and communicating value, which can be done without changing prices.”', '“管理价格意味着改进系统、流程和技能、传达价值，这些不改价格也能做。”'), cat='m6', why=T('The truth behind myth 6: it is far more complex, and simpler, than changing prices, and it needs an organisational transformation.', '迷思 6 背后的真相：它比改价格复杂得多，也简单得多，并需要组织层面的转变。')),
    ]
    return dict(
        id=f'{CID}-pricing-cost',
        title=T('Why is price the lever firms use worst?', '为什么价格是企业用得最差的杠杆？'),
        description=T('How much a price change moves profit and demand, what the six pricing myths get wrong, and how cost-based pricing, scale and learning set the floor, with Coles.', '价格变动对利润和需求的影响有多大、六个定价迷思错在哪里，以及成本导向定价、规模和学习怎样设定底线，案例是 Coles。'),
        minutes=45,
        skills=[{'id': SK, 'name': T('Explaining and applying cost-based pricing and elasticity', '解释并应用成本导向定价和弹性')}],
        misconceptions=[
            {'id': 'cost-plus-is-enough', 'description': T('cost plus a markup is the right way to set a price', '成本加成就是定价的正确方法')},
            {'id': 'cut-price-more-profit', 'description': T('a price cut that raises volume always raises profit', '带来销量增长的降价总能提高利润')},
        ],
        steps=[
            read('puzzle', T('The cheapest lever, the least used', '最便宜的杠杆，却最少被好好使用'),
                 p(T("In most firms, said one pricing expert, prices are set by intuition, opinion, rules of thumb, dogma, or internal power fights. Yet price can move profit faster than almost any other lever. Coles reports 311 million dollars of cost savings in FY26 that it used to fund value, stores and digital: it understands that **cost and price are two ends of the same lever**.",
                     "一位定价专家说，大多数企业的价格是凭直觉、意见、经验法则、教条或内部权力斗争定出来的。可是价格比几乎任何其他杠杆都能更快地改变利润。Coles 报告 2026 财年有 3.11 亿澳元成本节省，用于投入价格、门店和数字化：它明白**成本和价格是同一根杠杆的两头**。")),
                 chapter=CH['puzzle']),
            predict('guess', SK, T("A firm with a 10% margin raises its price 1% and loses 2% of its volume. Does profit go up or down?", "一家毛利 10% 的企业把价格提高 1%，销量减少 2%。利润上升还是下降？"),
                    [(T("Up: the extra margin on each sale outweighs the lost sales, because the margin is thin and the price is a large part of the profit", "上升：每笔多赚的钱超过了丢掉的销量，因为毛利薄，价格对利润的影响很大"), True),
                     (T("Down: it lost sales", "下降：丢了销量"), T("Check with numbers: 98 units at a margin of 11 earn more than 100 units at a margin of 10.", "用数字验证：98 件、每件毛利 11，赚得比 100 件、每件毛利 10 更多。")),
                     (T("No change: small changes do not matter", "不变：小变动无所谓"), T("That is pricing myth number two.", "那正是第二个迷思。")),
                     (T("It cannot be known", "无法知道"), T("It can, with the margin and the elasticity.", "知道毛利和弹性就可以算。"))],
                    T("Check with numbers: price 100, unit cost 90, volume 100, profit 1,000. New price 101, volume 98: profit = 98 × 11 = 1,078, **up 7.8%**. Pricing is a **big lever with small moves**. The dial shows when it turns against you: when demand is **elastic**.", "用数字验证：价格 100、单位成本 90、销量 100，利润 1,000。新价格 101，销量 98：利润 = 98 × 11 = 1,078，**上升 7.8%**。定价是**小动作大杠杆**。转盘会显示它什么时候对你不利：需求**有弹性**的时候。")),
            read('touch', T('Raise the price', '提高价格'),
                 p(T("A product with a unit cost of 6 sells 1,000 units at a price of 10. Drag the price and the elasticity (how strongly volume reacts). The demand curve is an illustration.", "一个单位成本为 6 的产品，在价格 10 时卖 1,000 件。拖动价格和弹性（销量反应有多强）。需求曲线是示意。")),
                 dial(T('Sliders for price and price elasticity of demand; outputs show volume, revenue and profit, and the curves show how they move with price.', '价格和需求价格弹性的滑块；输出为销量、收入和利润，曲线显示它们如何随价格变化。'),
                      sliders=[dict(id='pr', label=T('Price', '价格'), min=6, max=20, step=0.5, value=10, dec=1), dict(id='el', label=T('Elasticity (how strongly volume reacts to price)', '弹性（销量对价格的反应强度）'), min=0.3, max=3, step=0.1, value=0.7, dec=1)],
                      consts=dict(uc=6),
                      outs=[dict(id='q', label=T('Volume sold', '销量'), expr='1000*Math.pow(pr/10,-el)', dec=0), dict(id='rev', label=T('Revenue', '收入'), expr='pr*q', dec=0), dict(id='prof', label=T('Profit', '利润'), expr='(pr-uc)*q', dec=0)],
                      plot=dict(x='pr', ys=[dict(out='rev', label=T('revenue', '收入'), color='#2563EB'), dict(out='prof', label=T('profit', '利润'), color='#1F8A5B')], ymin=0, ylabel=T('money', '金额'), xlabel=T('price', '价格')),
                      presets=[dict(label=T('Inelastic: a necessity with few substitutes', '无弹性：必需品、替代品少'), set=dict(pr=10, el=0.5)), dict(label=T('Elastic: easy to switch', '有弹性：很容易换'), set=dict(pr=10, el=2.2))],
                      notes=[dict(when='el<1', text=T('**Inelastic** (below 1): volume falls less than price rises, so **a higher price raises revenue**. Few substitutes, little competition, or scarcity make demand inelastic.', '**无弹性**（小于 1）：销量降得比价格涨得少，所以**涨价会增加收入**。替代品少、竞争少或稀缺会使需求缺乏弹性。')),
                             dict(when='el>1', text=T('**Elastic** (above 1): volume falls faster than price rises, so **a higher price lowers revenue**; a cut would raise it, but check the margin.', '**有弹性**（大于 1）：销量降得比价格涨得快，所以**涨价会减少收入**；降价会增加收入，但要看毛利。')),
                             dict(when='prof<0', text=T('Profit is negative: price is below cost.', '利润为负：价格低于成本。'))],
                      caption=T("The demand curve (volume = 1,000 × (price ÷ 10) to the power of minus elasticity) and the unit cost of 6 are chosen for the demonstration, not taken from any company.", "需求曲线（销量 = 1,000 ×（价格 ÷ 10）的负弹性次方）和单位成本 6 是为演示而设，不取自任何公司。"), height=900),
                 chapter=CH['touch']),
            read('touch2', T('Scale pulls the floor down', '规模把底线拉低'),
                 p(T("Fixed cost 1,000,000 and variable cost 100 per unit (the lecture’s illustration). Unit cost is fixed cost over volume plus variable cost.", "固定成本 1,000,000，可变成本每件 100（课程里的示例）。单位成本 = 固定成本 ÷ 销量 + 可变成本。")),
                 dial(T('A slider for volume; the curve shows unit cost falling as fixed cost is spread over more units, and a price line to compare.', '销量滑块；曲线显示固定成本摊到更多件上后，单位成本下降，并画出价格线作对比。'),
                      sliders=[dict(id='vol', label=T('Volume', '销量'), min=1000, max=16000, step=500, value=1000)], consts=dict(fc=1000000, vc=100, price=300),
                      outs=[dict(id='fcu', label=T('Fixed cost per unit', '每件的固定成本'), expr='fc/vol', dec=1), dict(id='uc', label=T('Total unit cost', '单位总成本'), expr='fc/vol+vc', dec=1), dict(id='pf', label=T('Profit per unit at a price of 300', '价格 300 时每件利润'), expr='price-uc', dec=1), dict(id='pricel', label=T('Price', '价格'), expr='price', dec=0, hide=True)],
                      plot=dict(x='vol', ys=[dict(out='uc', label=T('unit cost', '单位成本'), color='#E4572E'), dict(out='pricel', label=T('price 300', '价格 300'), color='#2563EB')], ymin=0, ymax=1200, ylabel=T('per unit', '每件'), xlabel=T('volume', '销量')),
                      notes=[dict(when='uc>price', text=T('**Below break-even**: each unit loses money at this volume. The volume where the lines cross is the **break-even** volume.', '**低于盈亏平衡点**：这个销量下每件都亏钱。两条线相交处的销量就是**盈亏平衡**销量。')), dict(when='uc<=price', text=T('**Above break-even**: spreading fixed cost over more units leaves a profit per unit.', '**高于盈亏平衡点**：固定成本摊到更多件上，每件有利润。'))],
                      caption=T("The price of 300 is chosen for the demonstration.", "价格 300 是为演示而设。"), height=700)),
            read('touch3', T('Six myths, six truths', '六个迷思，六个真相'),
                 p(T("Hinterhuber’s six pricing myths each have a truth behind them. Match each truth to its myth.", "Hinterhuber 的六个定价迷思，每个背后都有一个真相。把每条真相配到它的迷思上。")),
                 tag(T('Six statements, each the truth behind one of the six myths; tag each with its myth.', '六条陈述，各是六个迷思之一背后的真相；标出对应的迷思。'), cats, items,
                     done=T("Six myths that kill profits: **costs are the basis**, **small changes have little impact**, **customers are highly price sensitive**, **products are hard to differentiate**, **high share means high profit**, **managing price means changing prices**.", "杀死利润的六个迷思：**成本是依据**、**小变动影响小**、**顾客高度价格敏感**、**产品难以差异化**、**高份额就是高利润**、**管理价格就是改价格**。"), height=900)),
            read('name', T('The framework, as the marker wants it', '阅卷人要的框架'),
                 p(T("Price has two roles at once. From the customer’s side, **value = benefits − price**; from the firm’s side, **profit = price − cost**. A **discount** raises customer value but lowers the firm’s margin and can change how quality is judged; an **increase** does the reverse. Pricing therefore sits between the two halves of value creation.", "价格同时扮演两个角色。从顾客一侧看，**价值 = 收益 − 价格**；从企业一侧看，**利润 = 价格 − 成本**。**折扣**提高顾客价值，却降低企业毛利，还可能改变对质量的判断；**涨价**则相反。所以定价处在价值创造两半之间。")),
                 ul(T("**Elasticity** measures how much quantity demanded responds to price, other things equal (Adam Smith’s “invisible hand” frames the discussion). It falls with **difficulty of substitution, little competition, scarcity**, and depends on the **buying centre** (who pays, where, how, when). When demand is inelastic, consumer surplus is larger and some buyers will pay a high price: the idea of pricing is to **move consumer surplus to the firm**.", "**弹性**衡量需求量对价格的反应程度，其他条件不变（Adam Smith 的“看不见的手”是讨论的背景）。它随**难以替代、竞争少、稀缺**而下降，也取决于**购买中心**（谁付钱、在哪、怎么付、何时付）。需求无弹性时，消费者剩余更大，有些买家愿意付高价：定价的思路就是**把消费者剩余转给企业**。"),
                    T("**Pricing objectives**: an internal orientation (profit maximisation, volume or share, product and quality), a competitive orientation (entry barriers, avoiding attack, holding position), or a political or external one (avoiding political trouble). Four forces: costs, competition, substitutes, unique value proposition.", "**定价目标**：内部导向（利润最大化、销量或份额、产品与质量）、竞争导向（进入壁垒、避免攻击、维持地位）、或政治/外部导向（避免政治麻烦）。四种力量：成本、竞争、替代品、独特的价值主张。"),
                    T("**Cost-based pricing** (used by roughly 60 to 80% of companies): apply a standard percentage **markup** to cost of goods sold. The **floor** (break-even price) is where there is no profit; the **ceiling** is where there is no demand; value-based pricing works between them. Direct costs go to one product (parts, labour); indirect costs (management, packaging, factory, overhead) are allocated. Markups are lowest in competitive industries such as supermarkets and highest where products are different and valuable.", "**成本导向定价**（大约 60% 到 80% 的企业使用）：在销货成本上加一个标准百分比的**加成**。**底线**（盈亏平衡价）是没有利润的价格；**天花板**是没有需求的价格；价值导向定价在两者之间。直接成本能归到某个产品（零部件、人工）；间接成本（管理、包装、工厂、间接费用）需要分摊。加成在超市这类竞争激烈的行业最低，在产品独特、价值高的行业最高。"),
                    T("A **long-term** price covers direct and indirect costs plus margin; a **short-term** price covers direct cost and gross margin and can win share from rivals. A product sold at or below cost to draw traffic is **loss-leader or dumping** pricing; below direct cost it may be illegal. Pros: easy and cheap. Cons: indirect cost allocation is hard, it uses a volume forecast to set the price (but price determines volume), it ignores competitors and demand, and it misses chances to charge more.", "**长期**价格覆盖直接和间接成本加毛利；**短期**价格覆盖直接成本和毛利，可以从对手手里抢份额。以等于或低于成本的价格卖商品来引流，是**引流品或倾销**定价；低于直接成本可能违法。优点：简单便宜。缺点：间接成本难分摊；用销量预测来定价（而价格决定销量）；忽略竞争对手和需求；错过多收钱的机会。"),
                    T("**Static cost management**: **economies of scale** (fixed cost spread over more units) and **target costing** (traditional: cost + margin = price; target: market price − margin = allowable cost; the gap says what to change). **Dynamic cost management**: the **experience or learning curve**, costs falling as cumulative output rises.", "**静态成本管理**：**规模经济**（固定成本摊到更多件上）和**目标成本法**（传统：成本 + 利润 = 价格；目标：市场价格 − 利润 = 允许成本；差距说明要改什么）。**动态成本管理**：**经验曲线/学习曲线**，累计产量上升，成本下降。")),
                 chapter=CH['name']),
            apply_q('apply', SK, T("Use Coles: it reports about 311 million dollars of cost savings in FY26, used to fund value, stores and digital, and sells its Own Brand ranges. Write four sentences: how this connects **cost and price**, which of **economies of scale, target costing or the learning curve** fits best, and one **limit** of cost-based thinking for a supermarket. Say what is inference.", "用 Coles：它报告 2026 财年约 3.11 亿澳元成本节省，用于投入价格、门店和数字化，并销售自有品牌系列。写四句话：这怎样联系**成本与价格**；**规模经济、目标成本法还是学习曲线**哪个最合适；以及超市采用成本导向思维的一个**局限**。说明哪些是推断。"),
                    [T("Links 311 million of cost savings to the ability to fund price and value", "把 3.11 亿成本节省联系到投入价格和价值的能力"), T("Chooses one concept with a reason, flagged as inference (scale of purchasing and logistics; savings programme)", "选一个概念并说明理由，标为推断（采购与物流规模；节省计划）"),
                     T("Gives a limit: cost-plus ignores competitors and demand; supermarkets have thin markups so price moves matter", "指出局限：成本加成忽略竞争和需求；超市加成薄，价格变动影响大"), T("Does not invent a markup or share figure", "不编造加成或份额数字")],
                    T("Coles reports 311 million dollars of cost savings in FY26 and uses them to fund value, stores and digital, which links cost to price: savings give room to hold prices down without losing margin. My inference is that scale is the closest concept, since a chain with more than 840 supermarkets spreads fixed costs of distribution and systems over a large volume, though the results do not say so. The limit of cost-based thinking is that a supermarket’s markups are thin and shoppers compare prices, so a price set from cost alone ignores competitors and demand: small moves in price matter a great deal when margins are thin. I have not used any markup figure because none is verified.",
                      "Coles 报告 2026 财年有 3.11 亿澳元成本节省，并用于投入价格、门店和数字化，这把成本和价格联系起来：节省给了它压住价格而不损失毛利的空间。我的推断是规模最贴近，因为拥有 840 多家超市的连锁企业把配送和系统的固定成本摊到很大的销量上，尽管业绩里并没有这样说。成本导向思维的局限是：超市的加成很薄，购物者会比价，所以只从成本出发定价会忽略竞争对手和需求：毛利薄时，价格的小动作影响很大。我没有使用任何加成数字，因为没有核实过。"),
                    T("Link cost to price, choose a concept, flag inference, give a limit.", "联系成本与价格，选一个概念，标明推断，给出局限。")),
            choice('neighbour', T('The look-alike', '长得像的那个'), SK,
                   T("A product’s price is set as cost plus 30%. A rival launches a cheaper alternative and volume drops. Which weakness of cost-based pricing is this?", "一个产品的价格是成本加 30%。对手推出更便宜的替代品，销量下降。这是成本导向定价的哪个弱点？"),
                   [(T("It ignores competitors’ prices and demand", "它忽略了竞争对手的价格和需求"), True), (T("It is too expensive to calculate", "计算成本太高"), T("Cost-based pricing is cheap and quick.", "成本导向定价便宜、快。")),
                    (T("It always sets prices too low", "它总是把价格定得太低"), T("It can also set them too high or too low; the issue is it does not look at the market.", "它也可能定得太高或太低；问题是它不看市场。"))],
                   T("Cost sets the floor; the market sets what is possible above it.", "成本设底线；底线之上能做什么由市场决定。"), purpose='check', chapter=CH['neighbour']),
            recall('r1', SK, T("From lesson 14: EVA includes a charge for…", "来自第 14 课：EVA 包含一项……的扣除"),
                   [(T("capital employed", "占用资本"), True), (T("only sales", "仅销售"), T("Sales are not what is charged.", "被扣除的不是销售。"))], T("Value to the firm is profit after the cost of capital.", "企业价值是扣除资本成本后的利润。"), first=True),
            recall('r2', SK, T("From lesson 13: buying from a cheaper supplier does not settle the choice because of…", "来自第 13 课：向更便宜的供应商购买不能一锤定音，是因为……"),
                   [(T("transaction costs added to the price", "价格之外的交易成本"), True), (T("supplier size", "供应商规模"), T("Size is not the issue.", "规模不是问题。"))], T("Total cost, not price alone.", "看总成本，不只是价格。")),
        ] + exam_three('exam', SK,
                       T("Question. (a) Explain cost-based pricing and why price elasticity matters to it. (b) Apply the ideas to Coles in Australia. (c) Make two pricing recommendations.", "题目。(a) 解释成本导向定价，以及价格弹性为何对它重要。(b) 把这些概念应用到澳大利亚的 Coles。(c) 给出两条定价建议。"),
                       (T("Write the **Explain** part.", "写**解释**部分。"),
                        [T("Cost-based pricing: a standard markup on cost; floor and ceiling; break-even", "成本导向定价：在成本上加标准加成；底线与天花板；盈亏平衡"), T("Elasticity: responsiveness of demand to price, and what affects it", "弹性：需求对价格的反应，以及影响因素"),
                         T("Its weakness: ignores competition and demand; economies of scale, target costing, learning curve", "弱点：忽略竞争和需求；规模经济、目标成本法、学习曲线"), T("Precise terms", "用词精确")],
                        T("Cost-based pricing sets a price by adding a standard markup to the cost of goods sold. Break-even or floor price is where profit is zero; the ceiling is where demand disappears. It is easy but ignores competitors and demand. Price elasticity measures how much quantity demanded changes when price changes: it is lower when substitutes are few, competition weak or the good scarce. If demand is inelastic a higher price raises revenue; if elastic it lowers it. Costs can be managed statically through economies of scale and target costing, and dynamically through the learning curve.",
                          "成本导向定价是在销货成本上加一个标准加成来定价。盈亏平衡价（底线）是利润为零的价格；天花板是需求消失的价格。它简单，但忽略竞争对手和需求。价格弹性衡量价格变化时需求量变化多少：替代品少、竞争弱或商品稀缺时较低。需求无弹性时涨价增加收入，有弹性时涨价减少收入。成本可以通过规模经济和目标成本法做静态管理，也可以通过学习曲线做动态管理。")),
                       (T("Write the **Apply** part.", "写**应用**部分。"),
                        [T("Uses true Coles facts: 311 million dollars of savings funding value; sales 45,580 million; more than 840 supermarkets; Own Brand ranges", "用真实的 Coles 事实：3.11 亿节省投入价格；销售 455.80 亿；840 多家超市；自有品牌系列"), T("Applies elasticity to groceries: necessities, substitutes, competition", "把弹性应用到杂货：必需品、替代品、竞争"),
                         T("Explains cost-price logic with cause and effect, flagged inference", "用因果解释成本与价格逻辑，标明推断"), T("A limit", "一个局限")],
                        T("Coles earned 45,580 million dollars of sales in FY26 and reports 311 million of cost savings used to fund value, stores and digital. Savings are the cost side of the price lever: they let Coles hold prices without losing margin, and scale across more than 840 supermarkets is the likely source, which is my inference. Groceries are necessities but with many substitutes and strong competition, so demand for a single item is elastic and a price rise on it moves shoppers elsewhere, while the basket as a whole is less elastic. Because markups in supermarkets are thin, a small price change moves profit a lot. The limit is that cost-plus alone cannot say which items to price keenly.",
                          "Coles 在 2026 财年销售额为 455.80 亿澳元，并报告 3.11 亿澳元成本节省用于投入价格、门店和数字化。节省是价格杠杆的成本一侧：让 Coles 压住价格而不损失毛利，其来源很可能是 840 多家超市的规模，这是我的推断。杂货是必需品，但替代品多、竞争激烈，所以单个商品的需求有弹性，涨价会把购物者赶去别处，而整个购物篮则弹性较小。因为超市的加成很薄，价格的小变动对利润影响很大。局限是：单靠成本加成说不清该对哪些商品定价更激进。")),
                       (T("Write the **Recommend** part: exactly two pricing recommendations.", "写**建议**部分：恰好两条定价建议。"),
                        [T("Exactly two from the analysis (price keenly where demand is elastic; use savings to fund targeted price cuts)", "恰好两条，从分析里推出（在需求有弹性的商品上价格更激进；用节省资助有针对性的降价）"), T("Each actionable", "每条可执行"), T("A risk named", "点出风险")],
                        T("First, use purchase data to find the items where shoppers compare prices most, and price those keenly while holding margin on less elastic items, because elasticity differs across the basket. The risk is that shoppers notice higher prices on other lines, so keep them modest and consistent. Second, direct a share of cost savings to price cuts on those items, because savings make cuts affordable without losing margin. The risk is a price war with rivals, so favour items where Coles’ Own Brand or scale gives an advantage.",
                          "第一，用购买数据找出购物者最爱比价的商品，对这些商品价格更激进，同时在弹性较低的商品上守住毛利，因为篮子里各商品的弹性不同。风险是购物者注意到其他品类价格更高，所以涨幅要小而一致。第二，把一部分成本节省用于这些商品的降价，因为节省让降价不必牺牲毛利。风险是与对手打价格战，所以优先选择 Coles 自有品牌或规模占优势的商品。")),
                       ),
    )
